package org.diy.liferecorder;
import android.app.*;import android.content.*;import java.util.*;import org.json.*;
/** Daily local reminder gated by fresh, observed sensor readings. */
public final class ContextReminder extends BroadcastReceiver {
 static void schedule(Context c){android.content.SharedPreferences p=c.getSharedPreferences("context-reminder",0);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent pi=PendingIntent.getBroadcast(c,2026,new Intent(c,ContextReminder.class).setAction("context-review"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);a.cancel(pi);if(!p.getBoolean("enabled",false))return;Calendar at=Calendar.getInstance();at.set(Calendar.HOUR_OF_DAY,p.getInt("hour",21));at.set(Calendar.MINUTE,p.getInt("minute",30));at.set(Calendar.SECOND,0);if(at.getTimeInMillis()<=System.currentTimeMillis())at.add(Calendar.DAY_OF_YEAR,1);a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),pi);}
 public void onReceive(Context c,Intent intent){if(Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())){schedule(c);return;}try(RecordStore store=new RecordStore(c)){check(c,store);}catch(Exception ignored){}schedule(c);}
 static boolean fresh(JSONObject r,long now){if(r==null||!r.has("value")||r.isNull("value")||!Double.isFinite(r.optDouble("value")))return false;long at=r.optLong("observed_at_epoch_ms",r.optLong("at_epoch_ms"));return at>0&&now>=at&&now-at<=15*60000;}
 static void check(Context c,RecordStore store){android.content.SharedPreferences p=c.getSharedPreferences("context-reminder",0);if(!p.getBoolean("enabled",false))return;Calendar now=Calendar.getInstance();int minute=now.get(Calendar.HOUR_OF_DAY)*60+now.get(Calendar.MINUTE),target=p.getInt("hour",21)*60+p.getInt("minute",30);String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(now.getTime());if(!((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled())return;if(minute<target||p.getString("last-day","").equals(day))return;PebbleContext x=new PebbleContext(store,null);JSONObject heart=x.values.get("heart_rate"),light=x.values.get("light");if(heart==null||light==null||heart.optDouble("value",0)<=0||light.optDouble("value",-1)<0||!fresh(heart,now.getTimeInMillis())||!fresh(light,now.getTimeInMillis())||heart.optDouble("value")>=p.getInt("heart",70)||light.optDouble("value")>=p.getInt("lux",50))return;NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("context-review","静心回忆",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent tap=PendingIntent.getActivity(c,2026,new Intent(c,MainActivity.class).putExtra("page","memory"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);try{manager.notify(2026,new Notification.Builder(c,"context-review").setSmallIcon(R.drawable.ic_record).setContentTitle(AppLanguage.text(c,"给今天留一点回想的时间")).setContentText(AppLanguage.text(c,"最近观察符合你设置的条件，轻点回看生活片段。")).setContentIntent(tap).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).build());p.edit().putString("last-day",day).apply();}catch(SecurityException ignored){}}
}
